pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address newOperator, address originalOperator, uint256 amount) public {
        vm.assume(newOperator != originalOperator);
        vm.assume(newOperator != address(0));
        vm.assume(originalOperator != address(0));
        vm.assume(amount > 0);

        // Setup: set initial operator to originalOperator
        vm.prank(address(this));
        c.setOperator(originalOperator);

        // Owner changes operator to newOperator
        vm.prank(address(this));
        c.setOperator(newOperator);

        // originalOperator tries to call depositAndStake
        vm.prank(originalOperator);
        bool ok = true;
        try c.depositAndStake(amount) { ok = true; } catch { ok = false; }

        // originalOperator should be rejected because operator was changed
        assertTrue(!ok);
    }
}

