contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(bool shutdown) public {
        vm.assume(shutdown == true);
        ICVXBooster booster = ICVXBooster(address(c.booster()));
        vm.mockCall(
            address(booster),
            abi.encodeWithSelector(booster.poolInfo.selector, c.cvxPoolInfo().pId),
            abi.encode(ICVXBooster.PoolInfo(address(0), address(0), address(0), address(0), false, shutdown))
        );
        assertTrue(c.isCvxShutdown() == shutdown);
    }
}

interface ICVXBooster {
    struct PoolInfo {
        address lptoken;
        address token;
        address gauge;
        address crvRewards;
        address stash;
        bool shutdown;
    }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
}

